spec.expr:
sum by (kind) (
  count_over_time(
    {
      job="loki.source.kubernetes_events",
      namespace=~"$alloyNamespace"
    }
      |~ "(?i)$logSearch"
      | name=~"(${alloyRole:regex}).*|.+-validate-(agent|gateway)(-.*)?"
      | name=~"$alloyPod"
    [$__auto]
  )
)

sum by (reason) (
  count_over_time(
    {
      job="loki.source.kubernetes_events",
      namespace=~"$alloyNamespace"
    }
      |~ "(?i)$logSearch"
      | name=~"(${alloyRole:regex}).*|.+-validate-(agent|gateway)(-.*)?"
      | name=~"$alloyPod"
    [$__auto]
  )
)

sum by (component_id) (
  rate(
    {
      app=~"$alloyRole",
      namespace=~"$alloyNamespace",
      level=~"WARN|WARNING|ERROR|CRITICAL|FATAL"
    }
      |~ "(?i)$logSearch"
      | pod=~"$alloyPod"
      | logfmt component_id
    [$__auto]
  )
) * 60

{
  app=~"$alloyRole",
  namespace=~"$alloyNamespace",
  level=~"$logLevelList"
}
  |~ "(?i)$logSearch"
  | pod=~"$alloyPod"

sum by (app, level) (
  rate(
    {
      app=~"$alloyRole",
      namespace=~"$alloyNamespace",
      level=~"$logLevelList"
    }
      |~ "(?i)$logSearch"
      | pod=~"$alloyPod"
    [$__auto]
  )
)

{
  app=~"$alloyRole",
  namespace=~"$alloyNamespace",
  level=~"WARN|WARNING|ERROR|CRITICAL|FATAL"
}
  |~ "(?i)$logSearch"
  | pod=~"$alloyPod"

sum(
  rate(
    {
      app=~"$alloyRole",
      namespace=~"$alloyNamespace",
      level=~"WARN|WARNING|ERROR|CRITICAL|FATAL"
    }
      |~ "(?i)$logSearch"
      | pod=~"$alloyPod"
    [1m]
  )
) * 60

{
  job="loki.source.kubernetes_events",
  namespace=~"$alloyNamespace",
  level="WARN"
}
  |~ "(?i)$logSearch"
  | name=~"(${alloyRole:regex}).*|.+-validate-(agent|gateway)(-.*)?"
  | name=~"$alloyPod"

max by (pod) (
